  significance=dict(statement=('Normal-liver comparator: '+pc if fid=='F4' else 'The authors describe this panel as: '+pc),role='background' if fid=='F4' else 'diagnostic_evidence',clinical_fact_status='unreviewed_annotation',basis='caption',visual_cue=None,evidence=[pe],certainty='clear')
  ps.append(dict(panel=letter,general_description=general,detailed_description=detail,image_kind='medical_imaging' if fid=='F1' else 'microscopy',has_chart=bool(charts),charts=charts,imaging_modalities=[tag(mod,'pixels',cue=observations[0])],imaging_submodalities=sub,medical_domains=[tag('radiology' if fid=='F1' else 'pathology','caption',sid=sid)],body_parts=[body],mentioned_categories=[],pixel_observations=observations,caption_claims=[tag(pc,'caption',sid=sid,q=pc,doc=pc)],clinical_significance=[significance],diagram_relations=[],limitations=limits))
  assign.append(dict(panel=letter,patient_ids=[] if fid=='F4' else ['p1'],scope='unresolved' if fid=='F4' else 'individual',subject='unresolved' if fid=='F4' else 'patient' if fid=='F1' else 'patient_specimen',evidence=[ce]+([ev('b00009')] if fid=='F1' else [ev('b00028',seg['b00028'][:seg['b00028'].index('Therefore, some physicians')])] if fid=='F2' else [ev('b00028',seg['b00028'][seg['b00028'].index('Through in-depth analysis'):seg['b00028'].index('In normal liver tissue')])] if fid=='F3' else [ev('b00028','or only isolated bile ducts were left (Fig. 5).')] if fid=='F5' else [ev('b00029',seg['b00029'][seg['b00029'].index('Based on the morphology'):])] if fid in ['F6','F7','F8'] else [ev('b00031',seg['b00031'][seg['b00031'].index('Therefore, we speculate'):])] if fid=='F9' else []),rationale='Normal-liver comparison, tissue donor/index-case relationship unreported.' if fid=='F4' else 'Caption plus explicit local index-case figure callout establish ownership; no identity inferred from appearance.'))
